/**
 * In-memory SQLite fixture: migrate, seed a tenant pair, reset between tests.
 *
 * Repository and service suites call `setupTestDb()` once, `resetTestDb()` in
 * `beforeEach` and `seedTwoTenants()` when they need two organizations to
 * prove a query is org-scoped. The database is `:memory:`, so nothing here
 * touches the developer's `data/taskflow.db`.
 */
// Aliased on import: the contract calls it `useInMemoryDb`, which the
// react-hooks lint rule would otherwise mistake for a React hook here.
import { getDb, useInMemoryDb as attachInMemoryDb } from "@/server/db";
import { runMigrations } from "@/server/db/migrate";
import { organizations } from "@/server/db/schema/organizations";
import { users } from "@/server/db/schema/users";
import type { Organization } from "@/types/organization";
import { makeOrganization, ORG_A, ORG_B } from "./factories";

let migrated = false;

/** Points the singleton client at an in-memory database and migrates it. */
export async function setupTestDb(): Promise<void> {
  attachInMemoryDb();
  await runMigrations(":memory:");
  migrated = true;
}

/** Truncates every table, keeping the schema — cheaper than re-migrating. */
export async function resetTestDb(): Promise<void> {
  if (!migrated) await setupTestDb();

  const db = getDb();
  const tables = db.$client
    .prepare(
      "SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' AND name NOT LIKE '__drizzle%'",
    )
    .all() as readonly { name: string }[];

  db.$client.pragma("foreign_keys = OFF");
  for (const table of tables) {
    db.$client.prepare(`DELETE FROM "${table.name}"`).run();
  }
  db.$client.pragma("foreign_keys = ON");
}

/**
 * Inserts two organizations owned by two different users. Every "does this
 * query filter by orgId?" test seeds through here so the negative case is a
 * real row in a real other tenant, not an absence.
 */
export async function seedTwoTenants(): Promise<{
  orgA: Organization;
  orgB: Organization;
}> {
  const db = getDb();

  const orgA = makeOrganization({ id: ORG_A, name: "Acme", slug: "acme" });
  const orgB = makeOrganization({
    id: ORG_B,
    name: "Globex",
    slug: "globex",
    ownerId: orgA.ownerId,
  });

  await db
    .insert(users)
    .values({
      id: orgA.ownerId,
      email: "owner@example.com",
      name: "Test Owner",
      passwordHash: "scrypt:00:00",
      timezone: "UTC",
      createdAt: orgA.createdAt,
      updatedAt: orgA.updatedAt,
    })
    .onConflictDoNothing();

  for (const org of [orgA, orgB]) {
    await db.insert(organizations).values({
      id: org.id,
      name: org.name,
      slug: org.slug,
      ownerId: org.ownerId,
      plan: org.plan,
      logoUrl: org.logoUrl,
      trialEndsAt: org.trialEndsAt,
      // `OrganizationSettings` is flattened across columns on this table.
      defaultIssueStatus: org.settings.defaultIssueStatus,
      allowPublicProjects: org.settings.allowPublicProjects,
      requireTwoFactor: org.settings.requireTwoFactor,
      digestHourUtc: org.settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(org.settings.enabledFlagOverrides),
      archivedAt: org.archivedAt,
      createdAt: org.createdAt,
      updatedAt: org.updatedAt,
    });
  }

  return { orgA, orgB };
}
/**
 * Tenant shell: resolves the `Actor`, builds the flag snapshot and renders the
 * sidebar.
 *
 * Owner D. Everything below this layout can assume three invariants: an actor
 * exists, it belongs to this organization, and the flag snapshot was evaluated
 * against that organization's plan. `assertOrgScope()` is what turns the third
 * assumption into a guarantee.
 *
 * Must call (do not reimplement): resolveActorForOrg, snapshotFlags,
 * assertOrgScope
 */

import { notFound } from "next/navigation";
import type { ReactNode } from "react";
import type { LimitedResource } from "@/types/billing";
import { snapshotFlags } from "@/lib/feature-flags";
import { getSessionPrincipal } from "@/lib/session";
import { assertOrgScope } from "@/lib/tenant";
import { checkLimit } from "@/server/services/billing-service";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { listNotifications } from "@/server/services/notification-service";
import { resolveOrgBySlug } from "@/server/services/organization-service";
import { listProjects } from "@/server/services/project-service";
import { resolveActorForOrg } from "@/server/services/session-service";
import { DashboardShell } from "./_components/dashboard-shell";
import { OrgProvider } from "./_components/org-provider";
import { UnauthorizedActionError } from "@/actions/_lib/action-errors";

type LayoutParams = { orgSlug: string };

export const dynamic = "force-dynamic";

const SIDEBAR_PROJECT_LIMIT = 12;

/** The quota dimensions the shell's usage meters read. */
const SHELL_LIMIT_RESOURCES: readonly LimitedResource[] = [
  "seats",
  "projects",
];

export default async function Layout(props: {
  children: ReactNode;
  panel?: ReactNode;
  params: Promise<LayoutParams>;
}) {
  // Next.js 16: params is a Promise and MUST be awaited.
  const { orgSlug } = await props.params;

  const principal = await getSessionPrincipal();
  if (principal === null) {
    throw new UnauthorizedActionError();
  }

  const org = await resolveOrgBySlug(orgSlug);
  if (org === null) {
    notFound();
  }

  // A membership the caller does not have resolves to null, which is the same
  // 404 as an org that does not exist — see `_lib/tenant-context.ts`.
  const actor = await resolveActorForOrg(principal, orgSlug);
  if (actor === null) {
    notFound();
  }
  assertOrgScope(actor, org.id);

  const flags = snapshotFlags(buildFlagContext(actor, org));

  const [projects, notifications, limitChecks] = await Promise.all([
    listProjects(actor, { orgId: org.id, limit: SIDEBAR_PROJECT_LIMIT }),
    listNotifications(actor, {
      orgId: org.id,
      recipientId: actor.userId,
      unreadOnly: true,
      limit: 1,
    }),
    // Evaluated once per navigation so `usePlanLimits()` in the client tree
    // reads a real measurement instead of falling back to "no data".
    Promise.all(
      SHELL_LIMIT_RESOURCES.map((resource) => checkLimit(org.id, resource, 0)),
    ),
  ]);

  return (
    <OrgProvider
      org={org}
      actor={actor}
      flags={flags}
      limitChecks={limitChecks}
    >
      <DashboardShell
        org={org}
        actor={actor}
        flags={flags}
        projects={projects.items.map((row) => row.project)}
        unreadCount={notifications.total}
        pathname={`/${orgSlug}`}
        panel={props.panel}
      >
        {props.children}
      </DashboardShell>
    </OrgProvider>
  );
}
/**
 * Scans for issues past `dueAt` and emits `issue.overdue`, which the notification fan-out turns into alerts.
 *
 * Must call (do not reimplement): emit, shouldFilterArchived
 */
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import { shouldFilterArchived } from "@/lib/soft-delete";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";

/** How many organizations one pass sweeps. */
const ORG_BATCH = 50;

/** Archived issues are never overdue — an archived issue has no due date. */
const LIVE_ONLY = {} as const;

const logger = createLogger("overdue-issue-job");

/**
 * Issues already announced this process's lifetime. A later sweep still
 * finds a still-open, still-overdue issue — this is what keeps the job from
 * re-emitting `issue.overdue` for it on every pass.
 */
const reported = new Set<string>();

/** Test-only: clears the reported set so a fresh scenario starts empty. */
export function resetOverdueTracking(): void {
  reported.clear();
}

/**
 * Publishes one `issue.overdue` per still-open, past-due issue. The job owns
 * no notification logic: it announces the fact, and whoever cares (in-app
 * alerts, the digest, webhooks) reacts on the bus.
 */
export async function runOverdueIssueJob(now: Date): Promise<JobResult> {
  return runJob("overdue-issues", async (result) => {
    if (!shouldFilterArchived(LIVE_ONLY)) {
      logger.warn("archive scope misconfigured; skipping sweep", {});
      return;
    }

    const stamp = toIsoTimestamp(now);
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const overdue = await issueRepo.listOverdueIssues(orgId, stamp);

      for (const issue of overdue) {
        if (issue.dueAt === null) continue;
        if (reported.has(issue.id)) continue;

        try {
          await emit("issue.overdue", {
            orgId,
            actorId: null,
            occurredAt: stamp,
            issueId: issue.id,
            projectId: issue.projectId,
            dueAt: issue.dueAt,
            assigneeId: issue.assigneeId,
          });
          reported.add(issue.id);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to announce overdue issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }
    }
  });
}
