import { describe, expect, it } from \"vitest\";
import { lockReasonFor, WorkspaceLockedError } from \"@/lib/billing-lock\";
import { isDomainError, toAppError } from \"@/lib/errors\";
import { toIsoTimestamp } from \"@/types/common\";
import type { OrgId, SubscriptionId } from \"@/types/common\";
import type { Subscription } from \"@/types/billing\";

const end = toIsoTimestamp(\"2026-10-01T12:00:00.000Z\");
const subscription: Subscription = {
  id: \"subscription\" as SubscriptionId,
  orgId: \"workspace\" as OrgId,
  plan: \"growth\",
  interval: \"monthly\",
  status: \"active\",
  seats: 1,
  currentPeriodStart: toIsoTimestamp(\"2026-09-01T12:00:00.000Z\"),
  currentPeriodEnd: end,
  cancelAt: null,
  createdAt: end,
  updatedAt: end,
};
const before = new Date(\"2026-10-01T11:59:59.999Z\");
const at = new Date(end);
const after = new Date(\"2026-10-01T12:00:00.001Z\");

describe(\"workspace lock rule\", () => {
  it(\"allows absent and active subscriptions even after their period ends\", () => {
    expect(lockReasonFor(null, after)).toBeNull();
    expect(lockReasonFor(subscription, after)).toBeNull();
  });

  it(\"locks past-due subscriptions immediately\", () => {
    expect(lockReasonFor({ ...subscription, status: \"past_due\" }, before)).toBe(\"past_due\");
  });

  it(\"locks a trial at its exact period end\", () => {
    const trial = { ...subscription, status: \"trialing\" as const };
    expect(lockReasonFor(trial, before)).toBeNull();
    expect(lockReasonFor(trial, at)).toBe(\"trial_ended\");
    expect(lockReasonFor(trial, after)).toBe(\"trial_ended\");
  });

  it(\"honors scheduled cancellations, including the exact boundary\", () => {
    const canceled = { ...subscription, status: \"canceled\" as const, cancelAt: end };
    expect(lockReasonFor(canceled, before)).toBeNull();
    expect(lockReasonFor(canceled, at)).toBe(\"canceled\");
    expect(lockReasonFor(canceled, after)).toBe(\"canceled\");
    expect(lockReasonFor({ ...canceled, cancelAt: null }, before)).toBe(\"canceled\");
  });

  it(\"maps lock errors as domain errors with the lock reason\", () => {
    const error = new WorkspaceLockedError(subscription.orgId, \"trial_ended\");
    expect(isDomainError(error)).toBe(true);
    expect(toAppError(error)).toMatchObject({
      code: \"plan_limit_exceeded\",
      meta: { reason: \"trial_ended\" },
    });
  });
});
EOF
