import { hashToken } from \"@/lib/hash\";
import { toIsoTimestamp } from \"@/types/common\";
import { createTenant, issueInput, useTemporaryDatabase } from \"../server/_support/fixtures\";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => { cleanup(); });

it(\"refuses writes without publishing, preserves permission refusals and reads, and unlocks after choosing a plan\", async () => {
  const tenant = await createTenant(\"locked-writes\");
  const input = issueInput(tenant.org.id, tenant.project.id);
  await subscriptionRepo.cancelSubscription(tenant.org.id, toIsoTimestamp(new Date(0)));
  const published: unknown[] = [];
  const off = subscribe(\"issue.created\", (event) => { published.push(event); });
  try {
    await expect(issueService.createIssue(tenant.actors.member, input)).rejects.toBeInstanceOf(WorkspaceLockedError);
    await expect(issueService.createIssue(tenant.actors.viewer, input)).rejects.toBeInstanceOf(PermissionDeniedError);
    expect(published).toEqual([]);
    expect((await issueService.listIssues(tenant.actors.member, { orgId: tenant.org.id, limit: 10 })).total).toBe(0);
    expect((await getOrganizationSummary(tenant.actors.member, tenant.org.id)).lockReason).toBe(\"canceled\");
    expect((await billingService.getBillingSummary(tenant.actors.owner, tenant.org.id)).lockReason).toBe(\"canceled\");
    await billingService.changePlan(tenant.actors.owner, { orgId: tenant.org.id, plan: \"growth\", interval: \"monthly\" });
    await expect(billingService.assertWorkspaceWritable(tenant.org.id)).resolves.toBeUndefined();
    await issueService.createIssue(tenant.actors.member, input);
    expect(published).toHaveLength(1);
  } finally {
    off();
  }
});

it(\"leaves an invitation pending and creates no membership when acceptance is locked\", async () => {
  const tenant = await createTenant(\"locked-acceptance\");
  const user = await userRepo.insertUser({ email: \"new@locked.test\", name: \"New member\", passwordHash: \"seed\" });
  const token = \"pending-invitation-token\";
  const invitation = await invitationRepo.insertInvitation(tenant.org.id, {
    orgId: tenant.org.id, email: user.email, role: \"member\", expiresInDays: 14,
  }, tenant.userIds.owner, hashToken(token));
  await subscriptionRepo.cancelSubscription(tenant.org.id, toIsoTimestamp(new Date(0)));
  await expect(acceptInvitation(user.id, { token: \"invalid\" })).rejects.toThrow(/was not found/);
  await expect(acceptInvitation(user.id, { token })).rejects.toBeInstanceOf(WorkspaceLockedError);
  expect(await memberRepo.findMember(tenant.org.id, user.id)).toBeNull();
  expect((await invitationRepo.findInvitationByTokenHash(hashToken(token)))?.acceptedAt).toBeNull();
  expect((await invitationRepo.listPendingInvitations(tenant.org.id)).map((row) => row.id)).toContain(invitation.id);
});
